diff --git a/src/consumer.ts b/src/consumer.ts
index 6be3c9d..5c6d03d 100644
--- a/src/consumer.ts
+++ b/src/consumer.ts
@@ -1,8 +1,24 @@
 import type { Outbox, Update } from "./notify.ts";

+const MAX_ATTEMPTS = 5;
+const BASE_BACKOFF_MS = 1000;
+
+const shouldRetry = (update: Update, now: number): boolean => {
+  const attemptCount = update.attemptCount || 0;
+  if (attemptCount >= MAX_ATTEMPTS) return false;
+
+  const lastAttempt = update.lastAttemptAt || 0;
+  const backoffMs = BASE_BACKOFF_MS * Math.pow(2, attemptCount);
+  return now - lastAttempt >= backoffMs;
+};
+
 export const drain = (outbox: Outbox, now: number, apply: (update: Update) => boolean): number => {
   let delivered = 0;
   for (const update of outbox.pending()) {
+    if (!shouldRetry(update, now)) continue;
+
+    outbox.recordAttempt(update.id, now);
+
     if (!apply(update)) continue;
     outbox.markDelivered(update.id, now);
     delivered += 1;
diff --git a/src/notify.ts b/src/notify.ts
index 3de32af..2cf0b41 100644
--- a/src/notify.ts
+++ b/src/notify.ts
@@ -3,14 +3,22 @@ export interface Update {
   accountId: string;
   body: string;
   deliveredAt: number | null;
+  lastAttemptAt?: number;
+  attemptCount?: number;
 }

 export interface Outbox {
   append: (update: Update) => void;
   pending: () => readonly Update[];
   markDelivered: (id: string, at: number) => void;
+  recordAttempt: (id: string, at: number) => void;
 }

 export const enqueue = (outbox: Outbox, update: Update): void => {
-  outbox.append({ ...update, deliveredAt: null });
+  outbox.append({
+    ...update,
+    deliveredAt: null,
+    attemptCount: 0,
+    lastAttemptAt: 0,
+  });
 };
